#include <iostream>
#include <stdexcept>
double calculate(double left, char op, double right) {
    switch (op) {
        case '+': return left + right;
        case '-': return left - right;
        case '*': return left * right;
        case '/': if (right != 0.0) return left / right; throw std::invalid_argument("division by zero");
        default: throw std::invalid_argument("unknown operator");
    }
}
int main() { std::cout << calculate(18.0, '/', 4.0) << '\n'; }
